<!doctype html><html><head><meta charset="utf-8"><title>{{ $event->name }} · Summary</title><style>body{font:14px/1.5 Arial;color:#111827;max-width:900px;margin:35px auto;padding:0 20px}header{display:flex;justify-content:space-between;border-bottom:3px solid #f59e0b;padding-bottom:18px}h1{margin:0}h2{margin-top:28px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.box{border:1px solid #ddd;padding:12px;border-radius:8px}.muted{color:#6b7280}.row{padding:8px 0;border-bottom:1px solid #eee}.actions{margin-bottom:20px}@media print{.actions{display:none}body{margin:0}}</style></head><body>
<div class="actions"><button onclick="window.print()">Print / Save PDF</button></div><header><div><h1>{{ $event->name }}</h1><div>{{ $event->categoryLabel() }} · {{ $event->event_date->format('F j, Y') }}</div></div><strong>Imprint Customs</strong></header>
<h2>Event</h2><div class="grid"><div class="box"><span class="muted">Venue</span><br><strong>{{ $event->venue ?: 'Not set' }}</strong></div><div class="box"><span class="muted">Schedule</span><br><strong>{{ $event->start_time ?: 'Not set' }} {{ $event->end_time ? '– '.$event->end_time : '' }}</strong></div><div class="box"><span class="muted">Contact</span><br><strong>{{ $event->contact_person ?: 'Not set' }} · {{ $event->contact_number ?: 'No phone' }}</strong></div><div class="box"><span class="muted">Status</span><br><strong>{{ str($event->status)->headline() }}</strong></div></div>
<h2>Production</h2>@if($event->coverage)<div class="grid"><div class="box">Shooter<br><strong>{{ $event->coverage->shooter?->name ?: 'Unassigned' }}</strong></div><div class="box">Editors<br><strong>{{ collect([$event->coverage->photoEditor?->name,$event->coverage->videoEditor?->name])->filter()->unique()->join(', ') ?: 'Unassigned' }}</strong></div><div class="box">Photo<br><strong>{{ App\Models\Coverage::STATUSES[$event->coverage->photo_status] }}</strong></div><div class="box">Video<br><strong>{{ App\Models\Coverage::STATUSES[$event->coverage->video_status] }}</strong></div></div>@else<p>No coverage record.</p>@endif
<h2>Tasks</h2>@forelse($event->tasks as $task)<div class="row">{{ $task->title }} — {{ App\Models\Task::STATUSES[$task->status] }} · {{ $task->user?->name ?: 'Queue' }}</div>@empty<p>None.</p>@endforelse
<h2>Revision and delivery history</h2>@forelse($event->coverage?->revisions ?? [] as $revision)<div class="row">Round {{ $revision->round }}: {{ $revision->notes }} — {{ $revision->completed_at ? 'Completed' : 'Open' }}</div>@empty<p>No revisions.</p>@endforelse @if($event->coverage?->delivery_sent_at)<p>Final link sent {{ $event->coverage->delivery_sent_at->format('M j, Y g:i A') }} by {{ $event->coverage->deliverySender?->name }}.</p>@endif
<h2>Files</h2>@forelse($event->files as $file)<div class="row">{{ $file->name }} · {{ number_format($file->size/1024,1) }} KB</div>@empty<p>No files.</p>@endforelse
</body></html>
